package fr.cake.protocol;
import java.io.*;import java.util.UUID;
/** Bounded state only: no coordinates or executable data. Relay stamps the sender UUID. */
public record CosmeticState(int flags,int knife,int finish,int trail,int jump,int skin,float trailHue,float jumpHue,float trailSize,float trailLife,float trailDensity,float jumpSize,float jumpLife,float skinScale,int back,float backScale,float backSpeed) {
 public CosmeticState(int flags,int knife,int finish,int trail,int jump,int skin,float trailHue,float jumpHue,float trailSize,float trailLife,float trailDensity,float jumpSize,float jumpLife,float skinScale){this(flags,knife,finish,trail,jump,skin,trailHue,jumpHue,trailSize,trailLife,trailDensity,jumpSize,jumpLife,skinScale,0,.5f,.4f);}
 public record Message(UUID player,CosmeticState state){}
 public static final int MAGIC=0x43414b45,VERSION=3,MAX_BYTES=96;
 public CosmeticState{if((flags&~31)!=0||knife<0||knife>21||finish<0||finish>13||trail<0||trail>7||jump<0||jump>11||skin<1||skin>32||back<0||back>12)throw new IllegalArgumentException("Invalid cosmetic enum");for(float f:new float[]{trailHue,jumpHue,trailSize,trailLife,trailDensity,jumpSize,jumpLife,skinScale,backScale,backSpeed})if(!Float.isFinite(f)||f<0||f>1)throw new IllegalArgumentException("Invalid cosmetic value");}
 public byte[] packet(UUID player){return encode(player,this);}
 public static byte[] encode(UUID player,CosmeticState s){try{var bytes=new ByteArrayOutputStream();var o=new DataOutputStream(bytes);o.writeInt(MAGIC);o.writeByte(VERSION);o.writeBoolean(s!=null);o.writeLong(player.getMostSignificantBits());o.writeLong(player.getLeastSignificantBits());if(s!=null){for(int n:new int[]{s.flags,s.knife,s.finish,s.trail,s.jump,s.skin})o.writeByte(n);for(float f:new float[]{s.trailHue,s.jumpHue,s.trailSize,s.trailLife,s.trailDensity,s.jumpSize,s.jumpLife,s.skinScale})o.writeFloat(f);o.writeByte(s.back);o.writeFloat(s.backScale);o.writeFloat(s.backSpeed);}return bytes.toByteArray();}catch(IOException e){throw new AssertionError(e);}}
 public static Message decode(byte[] b)throws IOException{if(b.length>MAX_BYTES)throw new IOException("Oversized payload");try{var in=new DataInputStream(new ByteArrayInputStream(b));if(in.readInt()!=MAGIC)throw new IOException("Unknown protocol");int version=in.readUnsignedByte();if(version!=2&&version!=3)throw new IOException("Unknown protocol");boolean present=in.readBoolean();var id=new UUID(in.readLong(),in.readLong());var state=present?new CosmeticState(in.readUnsignedByte(),in.readUnsignedByte(),in.readUnsignedByte(),in.readUnsignedByte(),in.readUnsignedByte(),in.readUnsignedByte(),in.readFloat(),in.readFloat(),in.readFloat(),in.readFloat(),in.readFloat(),in.readFloat(),in.readFloat(),in.readFloat(),version==3?in.readUnsignedByte():0,version==3?in.readFloat():.5f,version==3?in.readFloat():.4f):null;if(in.available()!=0)throw new IOException("Trailing data");return new Message(id,state);}catch(IllegalArgumentException e){throw new IOException("Invalid state",e);}}
}
